    // head if the high-order bit is set.
    var prefix00 = ((value[0] & 0x80) !== 0);
    var length = value.length + (prefix00 ? 1 : 0);
    var result = new Buffer(length + 4);
    var offset = 0;

    result.writeUInt32BE(length, offset);
    offset += 4;

    if (prefix00) {
	result[offset] = 0;
	offset++;
    }

    value.copy(result, offset);
    return result;
